#pragma once

// Which places sell fuel (jump charge): src/assets/data/fuel/fuel_stations.json, generated by
// tools/colonization_lab/fuel_stations.py (docs/FUEL_STATIONS.md). Keyed by the RUNTIME hub id (= the world-site id;
// Sol's hubs keep their own ids). Every inhabited hub with a market, the placement pass's refuelling stations, the
// runtime demo cities; the illegal ones (pirates, smugglers, proposed black tankers) are data only for now.
#include <string>
#include <unordered_map>
#include <vector>

#include "src/game/fuel/RefuelRules.h"

namespace game::fuel
{
struct FuelStation
{
    std::string id;
    std::string name;
    int systemId = -1;            // -1: deep space
    std::string kind;             // hub | refuel_point | small | grey | illegal
    std::string legality;         // legal | grey | illegal
    bool illegal = false;
    bool proposed = false;        // proposed by the fuel pass, not placed by the placement pass
    double stockT = 0.0;          // jump charge in stock (t)
    PumpSpec pump;
    double priceHintCrPerT = 0.0; // the market's jump_charge price (for the economy interface)
    double priceFactor = 1.0;     // the station's markup over it
    double risk = 0.0;            // illegal: the buyer's risk 0..1
};

class FuelStationCatalog
{
public:
    FuelStationCatalog() = default;
    // the game's catalog (the data file, loaded once)
    static const FuelStationCatalog& instance();

    // parse a catalog (the data file's text); false on a parse error - the unit test feeds its own text
    bool loadFromText(const std::string& text);

    [[nodiscard]] bool loaded() const { return m_loaded; }
    [[nodiscard]] const FuelStation* find(const std::string& hubId) const;
    // the station sells jump charge to an ordinary pilot (a legal or grey station with stock)
    [[nodiscard]] bool sellsFuel(const std::string& hubId) const;
    [[nodiscard]] const std::vector<FuelStation>& stations() const { return m_stations; }

private:
    bool m_loaded = false;
    std::vector<FuelStation> m_stations;
    std::unordered_map<std::string, std::size_t> m_index;
};
} // namespace game::fuel
